mapper.select:
select * from nad_application

    and application_type = #{applicationType}
    and current_status = #{currentStatus}
    and current_stage_id = #{stageId}
    and assignee_user_id = #{assigneeUserId}
    and (assignee_user_id = #{scopeUserId} or assignee_user_id is null)
    and id = cast(#{q} as unsigned)

order by create_time desc
